        "badges_2" to intArrayOf(54,21,256,223, 322,19,507,224, 572,21,773,223, 838,19,1023,224, 1087,21,1288,223, 1345,21,1546,223, 62,236,248,442, 314,238,515,441, 579,237,765,442, 830,238,1034,443, 1094,236,1281,442, 1345,238,1546,441, 54,455,256,657, 321,453,508,654, 572,452,773,657, 837,454,1024,654, 1087,453,1288,657, 1344,455,1546,658, 42,658,268,893, 296,656,535,893, 559,657,786,893, 811,656,1050,893, 1075,658,1301,893, 1333,658,1559,893),
        "badges_3" to intArrayOf(37,17,238,218, 292,12,481,220, 536,17,737,218, 791,7,995,226, 1051,6,1275,230, 1315,0,1570,236, 44,233,232,438, 281,230,493,444, 532,223,741,448, 792,236,995,437, 1066,231,1266,444, 1352,237,1540,439, 29,443,248,663, 288,444,486,660, 536,452,737,654, 789,440,999,665, 1066,452,1266,653, 1347,452,1547,652, 39,663,237,877, 278,660,496,880, 543,667,731,873, 789,665,999,877, 1066,671,1266,870, 1342,657,1551,884),
        "badges_4" to intArrayOf(40,31,269,273, 312,29,516,273, 568,31,777,272, 816,33,1051,268, 1090,30,1296,276, 1308,9,1589,295, 40,325,269,566, 312,322,516,567, 569,323,776,566, 816,325,1051,561, 1058,303,1330,587, 1349,320,1555,564, 40,621,269,862, 312,618,516,863, 538,597,811,885, 816,622,1051,857, 1091,616,1297,862, 1312,598,1584,881),
