        "gear_4" to intArrayOf(288,22,535,237, 564,24,784,237, 817,21,1052,233, 1082,17,1333,231, 288,240,535,441, 564,244,784,438, 817,242,1054,443, 1079,231,1337,450, 286,444,542,663, 564,455,786,658, 817,453,1052,657, 1082,453,1317,653, 288,666,535,860, 563,664,784,860, 815,667,1052,860, 1061,653,1343,893)
    )

    /** Measured rectangle of [index] on [sheetName], or null when the sheet/index is not in the table. */
    fun rectOf(sheetName: String, index: Int): IntArray? {
        val a = rects[sheetName] ?: return null
        if (index < 0 || index * 4 + 3 >= a.size) return null
        return intArrayOf(a[index * 4], a[index * 4 + 1], a[index * 4 + 2], a[index * 4 + 3])
    }
}

/**
 * Crops [index] of [sheetName] with the measured rectangle (falls back to the uniform [cols] x [rows] grid when the
 * sheet is not measured) and scales it so the longer side is at most [maxSide].
 */
fun cropMeasuredScaled(bitmap: Bitmap, sheetName: String, cols: Int, rows: Int, index: Int, maxSide: Int): Bitmap {
    val r = SheetRects.rectOf(sheetName, index) ?: return cropCellScaled(bitmap, cols, rows, index, maxSide)
    val sx = bitmap.width.toFloat() / SheetRects.NATIVE_W
    val sy = bitmap.height.toFloat() / SheetRects.NATIVE_H
    val x = (r[0] * sx).toInt().coerceIn(0, bitmap.width - 1)
    val y = (r[1] * sy).toInt().coerceIn(0, bitmap.height - 1)
    val w = ((r[2] * sx).toInt() - x).coerceIn(1, bitmap.width - x)
    val h = ((r[3] * sy).toInt() - y).coerceIn(1, bitmap.height - y)
    val cell = Bitmap.createBitmap(bitmap, x, y, w, h)
    val longest = maxOf(cell.width, cell.height)
    if (longest <= maxSide || maxSide <= 0) return cell
    val scale = maxSide.toFloat() / longest.toFloat()
    val sw = (cell.width * scale).toInt().coerceAtLeast(1)
    val sh = (cell.height * scale).toInt().coerceAtLeast(1)
    val scaled = Bitmap.createScaledBitmap(cell, sw, sh, true)
    if (scaled !== cell) cell.recycle()
    return scaled
}
